//! Replays `testdata/port/ingest/pipeline.json`, generated by the real Go
//! `TestPortIngestPipelineContract`: the whole one-shot pipeline (detect, hash,
//! store, queue, extraction routing, archive, classification, note writer,
//! annotation sidecar, reprocessing) over real files. Per step the result or
//! error text, engine/hook/log activity; per scenario the vault and archive
//! trees (bytes and modes) and the documents, jobs and extractions tables.
#![cfg(unix)]

use base64::{Engine as _, engine::general_purpose::STANDARD};
use regex::Regex;
use serde_json::{Map, Value, json};
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use symdesk_ingest::extract::Extraction;
use symdesk_ingest::ocr::{Context, Runner};
use symdesk_ingest::pipeline::{Engine, IngestOptions, IngestResult, Pipeline, PipelineError};
use symdesk_ingest::writer::{NoteLayout, NoteWriter, PaperlessMeta};
use symdesk_ingest::{Store, goos};
use time::OffsetDateTime;
use time::format_description::well_known::Rfc3339;

struct Temp(PathBuf);
impl Drop for Temp {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn write_private(path: impl AsRef<Path>, data: impl AsRef<[u8]>) {
    use std::io::Write;
    use std::os::unix::fs::OpenOptionsExt;
    let mut file = std::fs::OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .mode(0o600)
        .open(path.as_ref())
        .unwrap();
    file.write_all(data.as_ref()).unwrap();
    std::fs::set_permissions(path.as_ref(), std::fs::Permissions::from_mode(0o600)).unwrap();
}

fn fixture() -> Value {
    let path =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../testdata/port/ingest/pipeline.json");
    serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap()
}

fn s(v: &Value) -> &str {
    v.as_str().unwrap_or("")
}

fn bytes(v: &Value) -> Vec<u8> {
    v.as_str()
        .map(|t| STANDARD.decode(t).unwrap())
        .unwrap_or_default()
}

struct FakeEngine {
    mode: Mutex<String>,
    calls: Arc<Mutex<Vec<String>>>,
    root: String,
}

impl Engine for FakeEngine {
    fn extract(&self, _ctx: &Context, path: &str, kind: &str) -> Result<Extraction, String> {
        self.calls
            .lock()
            .unwrap()
            .push(format!("{kind}|{}", path.replace(&self.root, "<ROOT>")));
        match self.mode.lock().unwrap().as_str() {
            "fake-error" => Err("engine boom".into()),
            "fake-empty" => Ok(Extraction {
                text: String::new(),
                mime: kind.into(),
                engine: "fake-ocr".into(),
                language: String::new(),
            }),
            _ => Ok(Extraction {
                text: format!(
                    "OCR text for {} ({kind})\nSecond line 2024-05-06 mail@example.com",
                    goos::base(path)
                ),
                mime: kind.into(),
                engine: "fake-ocr".into(),
                language: "eng".into(),
            }),
        }
    }
}

struct Normalizer {
    root: String,
    tmp: Regex,
    stamp: Regex,
}

impl Normalizer {
    fn text(&self, t: &str) -> String {
        self.tmp
            .replace_all(&t.replace(&self.root, "<ROOT>"), ".tmp-N")
            .into_owned()
    }
    /// The YAML parser's own wording differs (declared limit); the failure
    /// class and the surrounding message are compared.
    fn yaml(&self, t: &str) -> String {
        match t.find("parse frontmatter: yaml: ") {
            Some(i) => format!("{}parse frontmatter: yaml: <PARSER>", &t[..i]),
            None => t.to_owned(),
        }
    }
    fn value(&self, v: &mut Value) {
        match v {
            Value::String(t) => *t = self.yaml(&self.text(t)),
            Value::Array(items) => items.iter_mut().for_each(|i| self.value(i)),
            Value::Object(map) => {
                for (k, item) in map.iter_mut() {
                    if k == "created_at" || k == "updated_at" {
                        *item = json!("<TS>");
                    } else {
                        self.value(item);
                    }
                }
            }
            _ => {}
        }
    }
}

fn yaml_wording(v: &mut Value) {
    match v {
        Value::String(t) => {
            if let Some(i) = t.find("parse frontmatter: yaml: ") {
                *t = format!("{}parse frontmatter: yaml: <PARSER>", &t[..i]);
            }
        }
        Value::Array(items) => items.iter_mut().for_each(yaml_wording),
        Value::Object(map) => map.values_mut().for_each(yaml_wording),
        _ => {}
    }
}

fn parse_time(v: &Value) -> Option<OffsetDateTime> {
    let t = s(v);
    (!t.is_empty()).then(|| OffsetDateTime::parse(t, &Rfc3339).unwrap())
}

fn options(v: &Value) -> Option<IngestOptions> {
    if v.is_null() {
        return None;
    }
    let tags = v["preset_tags"]
        .as_array()
        .map(|a| a.iter().map(|t| s(t).to_owned()).collect())
        .unwrap_or_default();
    let paperless = v
        .get("paperless")
        .filter(|p| !p.is_null())
        .map(|p| PaperlessMeta {
            document_id: p["document_id"].as_i64().unwrap_or(0),
            title: s(&p["title"]).into(),
            created: parse_time(&p["created"]),
            added: parse_time(&p["added"]),
            modified: parse_time(&p["modified"]),
            storage_path: s(&p["storage_path"]).into(),
            original_file_name: s(&p["original_file_name"]).into(),
            archived_file_name: s(&p["archived_file_name"]).into(),
            page_count: p["page_count"].as_i64().unwrap_or(0),
            url: s(&p["url"]).into(),
        });
    let layout = v
        .get("layout_subdir")
        .filter(|l| !l.is_null())
        .map(|l| NoteLayout {
            subdir: s(l).into(),
            base_name: s(&v["layout_base_name"]).into(),
        });
    Some(IngestOptions {
        preset_category: s(&v["preset_category"]).into(),
        preset_tags: tags,
        preset_correspondent: s(&v["preset_correspondent"]).into(),
        preset_document_type: s(&v["preset_document_type"]).into(),
        source_path_override: s(&v["source_path_override"]).into(),
        imported_from: s(&v["imported_from"]).into(),
        import_run_id: s(&v["import_run_id"]).into(),
        source_uri: s(&v["source_uri"]).into(),
        download_uri: s(&v["download_uri"]).into(),
        paperless,
        layout,
        allow_duplicate_content: v["allow_duplicate_content"].as_bool().unwrap_or(false),
        existing_vault_path: s(&v["existing_vault_path"]).into(),
        archive_path_override: s(&v["archive_path_override"]).into(),
        ocr_language: s(&v["ocr_language"]).into(),
    })
}

fn summarize(r: &IngestResult, n: &Normalizer) -> Value {
    let e = r.extract.clone().unwrap_or(Extraction {
        text: String::new(),
        mime: String::new(),
        engine: String::new(),
        language: String::new(),
    });
    json!({
        "source_path": n.text(&r.source_path),
        "sha256": r.sha256,
        "kind": r.kind,
        "text": e.text,
        "mime": e.mime,
        "engine": e.engine,
        "language": e.language,
        "vault_path": n.text(&r.vault_path),
        "archive_path": n.text(&r.archive_path),
        "category": r.category,
        "tags": r.tags,
        "correspondent": r.correspondent,
        "document_type": r.document_type,
        "sidecar_path": n.text(&r.sidecar_path),
        "extraction_count": r.extraction_count,
    })
}

fn walk(root: &Path, rel: &str, n: &Normalizer, out: &mut Vec<Value>) {
    let path = root.join(rel);
    let Ok(meta) = std::fs::symlink_metadata(&path) else {
        return;
    };
    let mode = format!("{:04o}", meta.permissions().mode() & 0o777);
    let mut entry = Map::new();
    entry.insert("path".into(), json!(rel));
    entry.insert("mode".into(), json!(mode));
    if meta.file_type().is_symlink() {
        entry.insert("type".into(), json!("symlink"));
    } else if meta.is_dir() {
        entry.insert("type".into(), json!("dir"));
        out.push(Value::Object(entry));
        let mut names: Vec<String> = std::fs::read_dir(&path)
            .unwrap()
            .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
            .collect();
        names.sort();
        for name in names {
            walk(root, &format!("{rel}/{name}"), n, out);
        }
        return;
    } else {
        entry.insert("type".into(), json!("file"));
        let data = std::fs::read(&path).unwrap();
        if std::str::from_utf8(&data).is_ok() && !data.contains(&0) {
            let normalized = n.text(std::str::from_utf8(&data).unwrap());
            let text = n
                .stamp
                .replace_all(&normalized, "ingested_at: <NOW>")
                .into_owned();
            if !text.is_empty() {
                entry.insert("text".into(), json!(text));
            }
        } else {
            let mut replaced = Vec::new();
            let hay = data.as_slice();
            let needle = n.root.as_bytes();
            let mut i = 0;
            while i < hay.len() {
                if hay[i..].starts_with(needle) {
                    replaced.extend_from_slice(b"<ROOT>");
                    i += needle.len();
                } else {
                    replaced.push(hay[i]);
                    i += 1;
                }
            }
            let replaced = regex::bytes::Regex::new(r"(?m-u)^ingested_at: [^ \t\n\r\x0B\x0C]+$")
                .unwrap()
                .replace_all(&replaced, &b"ingested_at: <NOW>"[..])
                .into_owned();
            entry.insert("b64".into(), json!(STANDARD.encode(replaced)));
        }
    }
    out.push(Value::Object(entry));
}

struct Env {
    root: PathBuf,
    pipeline: Pipeline,
    fake: Option<Arc<FakeEngine>>,
    calls: Arc<Mutex<Vec<String>>>,
    hooks: Arc<Mutex<Vec<String>>>,
    logs: Arc<Mutex<Vec<String>>>,
    norm: Normalizer,
}

fn run_case(case: &Value, tesseract: &str, base: &Path) -> Result<(), String> {
    let mut case = case.clone();
    for key in ["steps", "jobs"] {
        yaml_wording(&mut case[key]);
    }
    let case = &case;
    let sc = &case["scenario"];
    let id = s(&sc["id"]).to_owned();
    let root = base.join(&id);
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(root.join("src")).unwrap();
    std::fs::create_dir_all(root.join("tools")).unwrap();
    let rootstr = root.to_string_lossy().into_owned();
    let vault = root.join("vault");
    let vaultstr = vault.to_string_lossy().into_owned();
    for f in sc["files"].as_array().unwrap() {
        write_private(root.join("src").join(s(&f["name"])), bytes(&f["content"]));
    }
    let tess = root.join("tools/tesseract");
    std::fs::write(&tess, tesseract).unwrap();
    std::fs::set_permissions(&tess, std::fs::Permissions::from_mode(0o700)).unwrap();
    if sc["vault_is_file"].as_bool().unwrap_or(false) {
        write_private(&vault, "not a directory");
    } else {
        std::fs::create_dir_all(&vault).unwrap();
        std::fs::set_permissions(&vault, std::fs::Permissions::from_mode(0o700)).unwrap();
    }
    if sc["sidecar_blocked"].as_bool().unwrap_or(false) {
        write_private(vault.join(".symaira"), "blocker");
    }
    let store = Store::open(&root.join("db/docs.db")).map_err(|e| format!("store: {e}"))?;
    for r in sc["rules"].as_array().cloned().unwrap_or_default() {
        store.add_rule(s(&r[0]), s(&r[1]), s(&r[2])).unwrap();
    }
    let store = Arc::new(Mutex::new(store));
    let calls = Arc::new(Mutex::new(Vec::new()));
    let hooks = Arc::new(Mutex::new(Vec::new()));
    let logs = Arc::new(Mutex::new(Vec::new()));
    let norm = Normalizer {
        root: rootstr.clone(),
        tmp: Regex::new(r"\.tmp-\d+").unwrap(),
        stamp: Regex::new(r"(?m)^ingested_at: [^ \t\n\r\x0B\x0C]+$").unwrap(),
    };
    let mut pipeline = Pipeline::new(Arc::clone(&store), NoteWriter::new(&vaultstr));
    pipeline.extraction_profile = s(&sc["profile"]).into();
    let mut fake = None;
    match s(&sc["engine"]) {
        mode @ ("fake" | "fake-error" | "fake-empty") => {
            let engine = Arc::new(FakeEngine {
                mode: Mutex::new(mode.into()),
                calls: Arc::clone(&calls),
                root: rootstr.clone(),
            });
            pipeline.engine = Some(engine.clone());
            fake = Some(engine);
        }
        "runner" => {
            pipeline.engine = Some(Arc::new(Runner::new(
                &tess.to_string_lossy(),
                "pdftoppm-unused",
                "sips-unused",
                "eng",
            )));
        }
        _ => {}
    }
    match s(&sc["archive"]) {
        "dir" => pipeline.archive_dir = format!("{rootstr}/archive"),
        "in-vault" => pipeline.archive_dir = format!("{vaultstr}/archive/ingest"),
        "file" => {
            pipeline.archive_dir = format!("{rootstr}/archive-file");
            write_private(&pipeline.archive_dir, "x");
        }
        _ => {}
    }
    match s(&sc["vault_root"]) {
        "vault" => pipeline.vault_root = vaultstr.clone(),
        "other" => pipeline.vault_root = format!("{rootstr}/other-vault"),
        _ => {}
    }
    {
        let log = Arc::clone(&logs);
        pipeline.log = Box::new(move |line| log.lock().unwrap().push(line.to_owned()));
    }
    let hook_norm = (rootstr.clone(), Arc::clone(&hooks));
    match s(&sc["post_index"]) {
        mode @ ("ok" | "error") => {
            let (root, hooks) = hook_norm.clone();
            let fail = mode == "error";
            pipeline.post_index = Some(Box::new(move |path| {
                hooks
                    .lock()
                    .unwrap()
                    .push(format!("index|{}", path.replace(&root, "<ROOT>")));
                if fail {
                    Err("index boom".into())
                } else {
                    Ok(())
                }
            }));
        }
        _ => {}
    }
    match s(&sc["post_extract"]) {
        mode @ ("ok" | "error") => {
            let hooks = Arc::clone(&hooks);
            let fail = mode == "error";
            pipeline.post_extract = Some(Box::new(move |r, ex| {
                hooks.lock().unwrap().push(format!(
                    "extract|{}|{}|{}",
                    goos::base(&r.source_path),
                    r.extraction_count,
                    ex.len()
                ));
                if fail {
                    Err("extract boom".into())
                } else {
                    Ok(())
                }
            }));
        }
        _ => {}
    }
    let env = Env {
        root,
        pipeline,
        fake,
        calls,
        hooks,
        logs,
        norm,
    };

    let doc_paths = |id: i64| -> (String, String) {
        match env.pipeline.store.lock().unwrap().by_id(id) {
            Ok(d) => {
                let note = d.vault_path.unwrap_or_default();
                let mut archive = d.archive_path.unwrap_or_default();
                if !archive.starts_with('/') && !env.pipeline.vault_root.is_empty() {
                    archive = goos::join(&[&env.pipeline.vault_root, &archive]);
                }
                (note, archive)
            }
            Err(_) => (String::new(), String::new()),
        }
    };

    let mut problems = Vec::new();
    let expected_steps = case["steps"].as_array().unwrap();
    for (i, step) in sc["steps"].as_array().unwrap().iter().enumerate() {
        env.calls.lock().unwrap().clear();
        env.hooks.lock().unwrap().clear();
        env.logs.lock().unwrap().clear();
        let op = s(&step["op"]);
        let src = env
            .root
            .join("src")
            .join(s(&step["source"]))
            .to_string_lossy()
            .into_owned();
        let mut out = Map::new();
        out.insert("op".into(), json!(op));
        out.insert("result".into(), Value::Null);
        out.insert("error".into(), json!(""));
        out.insert("duplicate".into(), Value::Null);
        out.insert("is_duplicate".into(), json!(false));
        out.insert("no_archived_original".into(), json!(false));
        let n = &env.norm;
        let content = bytes(&step["content"]);
        match op {
            "ingest" => match env.pipeline.ingest(&src, options(&step["opts"]).as_ref()) {
                Ok(r) => {
                    out.insert("result".into(), summarize(&r, n));
                }
                Err(e) => {
                    out.insert("error".into(), json!(n.yaml(&n.text(&e.to_string()))));
                    if let PipelineError::Duplicate(d) = &e {
                        out.insert(
                            "duplicate".into(),
                            json!({
                                "source_path": n.text(&d.source_path),
                                "vault_path": n.text(&d.vault_path),
                                "archive_path": n.text(&d.archive_path),
                                "vault_root": n.text(&d.vault_root),
                            }),
                        );
                        out.insert("is_duplicate".into(), json!(true));
                    }
                }
            },
            "reprocess" => {
                let source = match s(&step["reprocess_source"]) {
                    "" => String::new(),
                    name => env
                        .root
                        .join("src")
                        .join(name)
                        .to_string_lossy()
                        .into_owned(),
                };
                match env.pipeline.reprocess(
                    step["doc_id"].as_i64().unwrap_or(0),
                    &source,
                    options(&step["opts"]).as_ref(),
                ) {
                    Err(e) => {
                        out.insert("error".into(), json!(n.yaml(&n.text(&e.to_string()))));
                        out.insert(
                            "no_archived_original".into(),
                            json!(matches!(e, PipelineError::NoArchivedOriginal(_))),
                        );
                    }
                    Ok(rr) => {
                        out.insert("already_running".into(), json!(rr.already_running));
                        if let Some(r) = &rr.result {
                            out.insert("result".into(), summarize(r, n));
                        }
                        let mut job = serde_json::to_value(&rr.job).unwrap();
                        n.value(&mut job);
                        out.insert("job".into(), job);
                    }
                }
            }
            "write" => write_private(&src, &content),
            "mkdir" => std::fs::create_dir_all(&src).unwrap(),
            "enqueue-reocr" => {
                env.pipeline
                    .store
                    .lock()
                    .unwrap()
                    .enqueue_reprocess_job(step["doc_id"].as_i64().unwrap())
                    .unwrap();
            }
            "set-engine" => {
                *env.fake.as_ref().unwrap().mode.lock().unwrap() =
                    String::from_utf8(content).unwrap();
            }
            "append-note" => {
                let (note, _) = doc_paths(1);
                let b = std::fs::read(&note).unwrap();
                let idx = b[4..].windows(5).position(|w| w == b"\n---\n").unwrap() + 5;
                let mut nb = b[..idx].to_vec();
                nb.extend_from_slice(&content);
                nb.extend_from_slice(&b[idx..]);
                write_private(&note, nb);
            }
            "set-lang" => {
                let (note, _) = doc_paths(1);
                let text = String::from_utf8(std::fs::read(&note).unwrap()).unwrap();
                let line = if content.is_empty() {
                    String::new()
                } else {
                    format!("ocr_language: {}\n", String::from_utf8_lossy(&content))
                };
                let re = Regex::new(r"(?m)^ocr_language:.*\n").unwrap();
                let updated = if re.is_match(&text) {
                    re.replace(&text, line.as_str()).into_owned()
                } else {
                    let idx = text[4..].find("\n---\n").unwrap() + 4 + 1;
                    format!("{}{}{}", &text[..idx], line, &text[idx..])
                };
                write_private(&note, updated);
            }
            "replace-note" => {
                write_private(doc_paths(step["doc_id"].as_i64().unwrap()).0, &content)
            }
            "remove-note" => {
                std::fs::remove_file(doc_paths(step["doc_id"].as_i64().unwrap()).0).unwrap()
            }
            "corrupt-archive" => {
                write_private(doc_paths(step["doc_id"].as_i64().unwrap()).1, "corrupted")
            }
            "remove-archive" => {
                std::fs::remove_file(doc_paths(step["doc_id"].as_i64().unwrap()).1).unwrap()
            }
            other => panic!("unknown op {other}"),
        }
        out.insert(
            "engine_calls".into(),
            json!(env.calls.lock().unwrap().clone()),
        );
        out.insert("hooks".into(), json!(env.hooks.lock().unwrap().clone()));
        out.insert(
            "logs".into(),
            json!(
                env.logs
                    .lock()
                    .unwrap()
                    .iter()
                    .map(|l| n.text(l))
                    .collect::<Vec<_>>()
            ),
        );
        let got = Value::Object(out);
        if got != expected_steps[i] {
            problems.push(format!(
                "step {i} ({op}):\n  got      {got}\n  expected {}",
                expected_steps[i]
            ));
        }
    }

    let n = &env.norm;
    let mut tree = Vec::new();
    for rel in ["vault", "archive", "archive-file"] {
        walk(&env.root, rel, n, &mut tree);
    }
    tree.sort_by(|a, b| s(&a["path"]).cmp(s(&b["path"])));
    if Value::Array(tree.clone()) != case["tree"] {
        let want = case["tree"].as_array().unwrap();
        let mut diffs = Vec::new();
        for i in 0..tree.len().max(want.len()) {
            if tree.get(i) != want.get(i) {
                diffs.push(format!(
                    "  tree[{i}] got {:?}\n  want {:?}",
                    tree.get(i),
                    want.get(i)
                ));
            }
        }
        problems.push(format!("tree:\n{}", diffs.join("\n")));
    }
    let store = env.pipeline.store.lock().unwrap();
    let docs = store.list_documents().unwrap();
    let mut docs_json = serde_json::to_value(&docs).unwrap();
    n.value(&mut docs_json);
    if docs_json != case["documents"] {
        problems.push(format!(
            "documents:\n  got  {docs_json}\n  want {}",
            case["documents"]
        ));
    }
    let jobs = store.list_jobs(1000).unwrap();
    let mut jobs_json = serde_json::to_value(&jobs).unwrap();
    n.value(&mut jobs_json);
    if jobs_json != case["jobs"] {
        problems.push(format!(
            "jobs:\n  got  {jobs_json}\n  want {}",
            case["jobs"]
        ));
    }
    let mut exs = Map::new();
    for d in docs.unwrap_or_default() {
        exs.insert(
            d.id.to_string(),
            serde_json::to_value(store.list_extractions(d.id).unwrap()).unwrap(),
        );
    }
    let mut exs_json = Value::Object(exs);
    n.value(&mut exs_json);
    if exs_json != case["extractions"] {
        problems.push(format!(
            "extractions:\n  got  {exs_json}\n  want {}",
            case["extractions"]
        ));
    }
    drop(store);
    let transcript: Vec<String> = std::fs::read_to_string(env.root.join("tools/log"))
        .map(|t| {
            t.strip_suffix('\n')
                .unwrap_or(&t)
                .split('\n')
                .map(|l| n.text(l))
                .collect()
        })
        .unwrap_or_default();
    if json!(transcript) != case["transcript"] {
        problems.push(format!(
            "transcript {transcript:?} != {}",
            case["transcript"]
        ));
    }
    if problems.is_empty() {
        Ok(())
    } else {
        Err(problems.join("\n"))
    }
}

#[test]
fn pipeline_scenarios_replay_go() {
    let fx = fixture();
    assert_eq!(fx["schema_version"], 1);
    let cases = fx["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 60, "pipeline fixture scenario count");
    let steps: usize = cases
        .iter()
        .map(|c| c["steps"].as_array().unwrap().len())
        .sum();
    assert_eq!(steps, 177, "pipeline fixture step count");
    let temp = Temp(std::env::temp_dir().join(format!("ingest-pipeline-{}", std::process::id())));
    let mut failures = Vec::new();
    let only = std::env::var("PIPELINE_ONLY").ok();
    for case in cases {
        let id = s(&case["scenario"]["id"]);
        if only.as_deref().is_some_and(|o| o != id) {
            continue;
        }
        if let Err(e) = run_case(case, s(&fx["tesseract"]), &temp.0) {
            failures.push(format!("== {id}\n{e}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} scenario(s) differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn negative_control_mutated_expectation_is_rejected() {
    let fx = fixture();
    let mut case = fx["cases"][0].clone();
    case["steps"][0]["result"]["category"] = json!("Mutated");
    let temp =
        Temp(std::env::temp_dir().join(format!("ingest-pipeline-neg-{}", std::process::id())));
    assert!(run_case(&case, s(&fx["tesseract"]), &temp.0).is_err());
    let mut case = fx["cases"][1].clone();
    case["tree"][2]["text"] = json!("tampered");
    assert!(run_case(&case, s(&fx["tesseract"]), &temp.0).is_err());
}
